mapper.select:
SELECT TAX_INPUT_ID, USER_ID, TAX_YEAR, BUSINESS_REGISTERED, AGE, STARTUP_RELIEF_APPLIED, BUSINESS_REGION, DEPENDENT_COUNT, DONATION_AMOUNT, SAVE_STATUS FROM tax_inputs WHERE USER_ID = #{userId} AND SAVE_STATUS = 'SAVED'
AND TAX_YEAR = #{taxYear}
ORDER BY UPDATED_AT DESC, TAX_INPUT_ID DESC

mapper.update:
UPDATE tax_inputs
SET UPDATED_AT = CURRENT_TIMESTAMP
WHERE TAX_INPUT_ID = #{taxInputId}

UPDATE tax_transactions
SET CATEGORY = #{category}
WHERE TAX_INPUT_ID = #{taxInputId}
AND TRANSACTION_ID = #{transactionId}

mapper.delete:
DELETE FROM tax_transactions
WHERE TAX_INPUT_ID = #{taxInputId}
AND TRANSACTION_ID = #{transactionId}
